<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\Gateway;

use Override;
use ArrayIterator;
use Civi\Lughauth\Features\Notification\Message\Domain\MessageAttributes;

/**
 * @template-extends ArrayIterator<int, MessageAttributes>
 */
class MessageAttributesSlide extends ArrayIterator
{
    public function __construct(
        private readonly ?MessageCursor $cursor,
        private readonly array $values
    ) {
        parent::__construct($values);
    }
    public function cursor(): ?MessageCursor
    {
        return $this->cursor;
    }
    public function values(): array
    {
        return $this->values;
    }
    #[Override]
    public function current(): ?MessageAttributes
    {
        return parent::current();
    }
}
